node --input-type=module <<'JS'
import {writeFile} from 'node:fs/promises';
const target=(await (await fetch('http://127.0.0.1:9222/json')).json()).find(t=>t.type==='page');
const ws=new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve,reject)=>{ws.addEventListener('open',resolve,{once:true});ws.addEventListener('error',reject,{once:true})});
let id=0;const pending=new Map();ws.addEventListener('message',e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}});
const send=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}))});
await send('Page.reload',{ignoreCache:true});
let loaded=false;for(let i=0;i<60&&!loaded;i++){const r=await send('Runtime.evaluate',{expression:"document.readyState==='complete'&&!!document.querySelector('#start')",returnByValue:true});loaded=r.result?.result?.value===true;if(!loaded)await new Promise(resolve=>setTimeout(resolve,100))}
await send('Runtime.evaluate',{expression:"document.querySelector('#start').click(); new Promise(resolve=>{let n=0;function frame(){if(++n<40)requestAnimationFrame(frame);else resolve()}requestAnimationFrame(frame)})",awaitPromise:true});
const shot=await send('Page.captureScreenshot',{format:'jpeg',quality:75,fromSurface:true});
await writeFile('/tmp/opencode/mobile-check.jpg',Buffer.from(shot.result.data,'base64'));
ws.close();
